output-exprs.el:
detalleMovimientos:if(
  and(
    a!isNotNullOrEmpty(pv!cifrasControl),
    length(pv!cifrasControl)> 0
  ),
 'type!{urn:com:appian:types:PIMF}PIMF_DETALLE_MOV_GENERADOS'(
   totalMovimientos: = tostring(pv!cifrasControl[1].totalRegistros),
   movExitosos: = tostring(pv!cifrasControl[1].registrosCumplieron),
   movFallidos: = tostring(pv!cifrasControl[1].registrosNoCumplieron)
 ),
 {}
)

